27	export function parseCopilotPricingHtml(html: string): CopilotModelRow[] {
28	  const $ = cheerio.load(html);
29	  const rows: CopilotModelRow[] = [];
30	
31	  $("table[aria-labelledby]").each((_, table) => {
32	    const slug = $(table).attr("aria-labelledby")!;
33	    const creator = CREATOR_NAMES[slug];
34	    if (!creator) return;
35	
36	    const headers = $(table)
37	      .find("thead th")
38	      .toArray()
39	      .map((th) => cellText($(th)));
40	    const col = (name: string) => headers.indexOf(name);
41	
42	    $(table)
43	      .find("tbody tr")
44	      .each((_, tr) => {
45	        const cells = $(tr).find("td").toArray();
46	        const at = (index: number) => (index === -1 ? null : cellText($(cells[index])));
47	
48	        rows.push({
49	          creator,
50	          model: at(col("Model"))!,
51	          releaseStatus: at(col("Release status"))!,
52	          category: at(col("Category"))!,
53	          tier: at(col("Tier")),
54	          thresholdInputTokens: parseThreshold(at(col("Threshold (input tokens)"))),
55	          price1mInput: parsePrice(at(col("Input")))!,
56	          price1mCachedInput: parsePrice(at(col("Cached input")))!,
57	          price1mCacheWrite: parsePrice(at(col("Cache write"))),
58	          price1mOutput: parsePrice(at(col("Output")))!,
59	        });
60	      });
61	  });
62	
63	  if (rows.length === 0) {
64	    throw new Error(
65	      "parseCopilotPricingHtml: no model rows found -- page structure may have changed",
