3	export type OpenCodeGoModelRow = {
4	  model: string;
5	  modelId: string | null;
6	  priceInput: number;
7	  priceOutput: number;
8	  priceCachedRead: number | null;
9	  priceCachedWrite: number | null;
10	  monthlyLimitUsd: number;
11	  requestsPer5h: number | null;
12	  requestsPerWeek: number | null;
13	  requestsPerMonth: number | null;
14	  endpoint: string | null;
15	  aiSdkPackage: string | null;
16	  modelTraining: string | null;
17	  dataRetentionDays: number | null;
18	  notes?: string;
19	};
