21	export function parseOpenCodeGoPricingHtml(html: string): OpenCodeGoModelRow[] {
22	  const $ = cheerio.load(html);
23	  const tables = $("table").toArray();
24	
25	  const pricingTable = findTableByHeaders($, tables, [
26	    "Model",
27	    "Input",
28	    "Output",
29	    "Cached Read",
30	    "Cached Write",
31	    "Monthly limit",
32	  ]);
33	  const requestsTable = findTableByHeaders($, tables, [
34	    "Model",
35	    "requests per 5 hour",
36	    "requests per week",
37	    "requests per month",
38	  ]);
39	  const endpointsTable = findTableByHeaders($, tables, [
40	    "Model",
41	    "Model ID",
42	    "Endpoint",
43	    "AI SDK Package",
44	  ]);
45	  const privacyTable = findTableByHeaders($, tables, ["Model", "Model training", "Data retention"]);
46	
47	  if (!pricingTable) {
48	    throw new Error(
49	      "parseOpenCodeGoPricingHtml: pricing table not found -- page structure may have changed",
50	    );
51	  }
52	
53	  const requestsByModel = rowsByModel($, requestsTable);
54	  const endpointsByModel = rowsByModel($, endpointsTable);
55	  const privacyByModel = rowsByModel($, privacyTable);
56	
57	  const rows: OpenCodeGoModelRow[] = [];
58	  for (const tr of $(pricingTable).find("tbody tr").toArray()) {
59	    const cells = $(tr).find("td").toArray();
60	    const model = cellText($(cells[0]));
61	    const { limit, note: limitNote } = parseMonthlyLimit($, cells[5]);
62	
63	    // The requests/endpoints/privacy tables list each model once under its base name
64	    // (no peak/off-peak or context-threshold split), so fall back to the base name
65	    // when the pricing table's variant-suffixed name has no exact match.
66	    const base = stripVariantSuffix(model);
67	    const req = requestsByModel.get(model) ?? requestsByModel.get(base);
68	    const ep = endpointsByModel.get(model) ?? endpointsByModel.get(base);
69	    const priv = privacyByModel.get(model) ?? privacyByModel.get(base);
70	    const missing = [!req && "requests", !ep && "endpoints", !priv && "privacy"].filter(
71	      (x): x is string => Boolean(x),
72	    );
73	    if (missing.length > 0) {
74	      console.warn(`opencode-go: "${model}" has no matching row in: ${missing.join(", ")}`);
75	    }
76	
77	    const { days, note: retentionNote } = parseDataRetention(priv?.[2] ?? null);
78	
79	    rows.push({
80	      model,
81	      modelId: ep?.[1] ?? null,
82	      priceInput: parsePrice(cellText($(cells[1])))!,
83	      priceOutput: parsePrice(cellText($(cells[2])))!,
84	      priceCachedRead: parsePrice(cellText($(cells[3]))),
85	      priceCachedWrite: parsePrice(cellText($(cells[4]))),
86	      monthlyLimitUsd: limit,
87	      requestsPer5h: req ? parseCount(req[1]) : null,
88	      requestsPerWeek: req ? parseCount(req[2]) : null,
89	      requestsPerMonth: req ? parseCount(req[3]) : null,
90	      endpoint: ep?.[2] ?? null,
91	      aiSdkPackage: ep?.[3] ?? null,
92	      modelTraining: priv?.[1] ?? null,
93	      dataRetentionDays: days,
94	      notes: [limitNote, retentionNote].filter(Boolean).join("; ") || undefined,
95	    });
96	  }
97	
98	  if (rows.length === 0) {
99	    throw new Error(
100	      "parseOpenCodeGoPricingHtml: no model rows found -- page structure may have changed",
101	    );
102	  }
103	  return rows;
104	}
