106	// Strips a trailing variant qualifier like " (Off-Peak)", " (Peak)", " (≤ 256K tokens)"
107	// so peak/off-peak and context-threshold pricing rows can still join against the
108	// requests/endpoints/privacy tables, which only list each model under its base name.
109	function stripVariantSuffix(model: string): string {
110	  return model.replace(/\s*\([^)]*\)\s*$/, "").trim();
111	}
112	
113	function findTableByHeaders($: cheerio.CheerioAPI, tables: any[], expected: string[]) {
114	  return tables.find((table) => {
115	    const headers = $(table)
116	      .find("thead th")
117	      .toArray()
118	      .map((th) => cellText($(th)));
119	    return expected.every((name) => headers.includes(name));
120	  });
121	}
122	
123	// Model name -> all cell texts for that row (index 0 is always the model name itself).
124	function rowsByModel($: cheerio.CheerioAPI, table: any): Map<string, string[]> {
125	  const map = new Map<string, string[]>();
126	  if (!table) return map;
127	  for (const tr of $(table).find("tbody tr").toArray()) {
128	    const cells = $(tr)
129	      .find("td")
130	      .toArray()
131	      .map((td) => cellText($(td)));
132	    map.set(cells[0], cells);
133	  }
134	  return map;
135	}
136	
137	function parseMonthlyLimit($: cheerio.CheerioAPI, cell: any): { limit: number; note?: string } {
138	  const $cell = $(cell);
139	  const strong = $cell.find("strong");
140	  if (strong.length > 0) {
141	    const del = $cell.find("del");
142	    const small = $cell.find("small");
143	    const base = del.length > 0 ? parsePrice(cellText(del)) : null;
144	    const promo = small.length > 0 ? cellText(small) : null;
145	    const note =
146	      base !== null
147	        ? `Promotional monthly limit (base $${base}): ${promo ?? ""}`.trim()
148	        : (promo ?? undefined);
149	    return { limit: parsePrice(cellText(strong))!, note };
150	  }
151	  return { limit: parsePrice(cellText($cell))! };
152	}
153	
154	function parseDataRetention(text: string | null): { days: number | null; note?: string } {
155	  if (text === null) return { days: null };
156	
157	  const hadFootnoteMark = text.endsWith("*");
158	  const stripped = hadFootnoteMark ? text.slice(0, -1) : text;
159	
160	  const match = stripped.match(/(\d+)\s*days/);
161	  if (!match) {
162	    return { days: null, note: text };
163	  }
164	  return { days: Number(match[1]), note: hadFootnoteMark ? "see page footnote *" : undefined };
165	}
166	
167	function parseCount(text: string): number {
168	  return parseInt(text.replace(/,/g, ""), 10);
169	}
170	
171	function parsePrice(text: string | null): number | null {
172	  if (text === null || text === "-") return null;
173	  return parseFloat(text.replace("$", ""));
174	}
175	
176	// Strips footnote/promo markup noise so plain-text extraction stays predictable;
177	// callers that need the sub-structure (e.g. <strong>/<del>/<small>) read it before calling this.
178	function cellText($cell: cheerio.Cheerio<any>): string {
179	  const clone = $cell.clone();
180	  clone.find("sup").remove();
181	  return clone.text().trim();
182	}
