export class NetworkError extends Error {
  url: string;
  status?: number;

  constructor(message: string, url: string, options?: { status?: number; cause?: unknown }) {
    super(message, { cause: options?.cause });
    this.name = "NetworkError";
    this.url = url;
    this.status = options?.status;
  }
}

export async function downloadHtml(url: string): Promise<string> {
  let res: Response;
  try {
    res = await fetch(url);
  } catch (err) {
    throw new NetworkError(`Request to ${url} failed: ${(err as Error).message}`, url, {
      cause: err,
    });
  }

  if (!res.ok) {
    const body = await res.text();
    throw new NetworkError(`${res.status} ${res.statusText} on ${url}: ${body}`, url, {
      status: res.status,
    });
  }
  return res.text();
}

export type PricingSource<Row> = {
  id: string;
  displayName: string;
  sourceUrl: string;
  outFile: string;
  notes: string;
  // Absolute path of the parser module, so a repair agent knows which file to rewrite.
  parserPath: string;
  parse: (html: string) => Row[];
};

import type { PricingSource } from "./source.ts";

export type ParserFailure = {
  source: PricingSource<unknown>;
  html: string;
  error: unknown;
};

// TODO: run a Pi agent via SDK to rewrite `source.parserPath` against the downloaded
// `html`, then retry parsing. For now this only reports the failure.
export async function repairParser({ source, error }: ParserFailure): Promise<void> {
  console.error(
    `[${source.id}] parser failed for ${source.sourceUrl}: ${error instanceof Error ? error.message : String(error)}\n` +
      `  Parser: ${source.parserPath}\n` +
      `  Automatic parser repair is not implemented yet; keeping existing ${source.outFile}.`,
  );
}

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { downloadHtml } from "./downloader.ts";
import { repairParser } from "./repair-parser.ts";
import type { PricingSource } from "./source.ts";

// Returns false when parsing failed (existing data file is left untouched).
// Network errors are not caught and abort the pipeline.
export async function refreshPricingSource<Row>(source: PricingSource<Row>): Promise<boolean> {
  const html = await downloadHtml(source.sourceUrl);

  let models: Row[];
  try {
    models = source.parse(html);
  } catch (error) {
    await repairParser({ source, html, error });
    return false;
  }

  await mkdir(path.dirname(source.outFile), { recursive: true });
  await writeFile(
    source.outFile,
    JSON.stringify(
      {
        sourceUrl: source.sourceUrl,
        fetchedAt: new Date().toISOString(),
        notes: source.notes,
        models,
      },
      null,
      2,
    ),
  );
  console.log(`Wrote ${models.length} ${source.displayName} models to ${source.outFile}`);
  return true;
}

